## Generates a distorted harmonic spectrum based on iterating the function "s = f*p to the d". The partials#present in the spectrum come from one of the series constructed by "SeriesArmonicas3.py".from SeriesArmonicas4 import *def espectro_distorsionado(fundamental, parciales, distorsion):		espectro 	= []									# List to store the distorted spectrum		while len(parciales) > 0:		un_parcial = parciales.pop(0)		parcial_distorsionado = pow(un_parcial, distorsion)		frecuencia_del_parcial = fundamental * parcial_distorsionado		if  frecuencia_del_parcial > 20000 :			break		else:			espectro.append(frecuencia_del_parcial)	return espectro
